(function () {
  var items = $input.all();
  var DECIDER = /\b(cto|cio|coo|ceo|founder|co-founder|vp|head of|director|chief|owner|managing)\b/i;
  var LEGACY = /(legacy|migration|modernization|modernisation|mainframe|cobol|php ?5|jquery|\.net framework|vb6|monolith|end[- ]of[- ]life)/i;
  var STAGES = { "pre-seed": 15, seed: 15, "series-a": 8, bootstrapped: 8 };
  var daysAgo = function (s) { var t = Date.parse(s || ""); return isNaN(t) ? 9999 : (Date.now() - t) / 86400000; };
  return items.map(function (l) {
    var reasons = [];
    var score = 0;
    var add = function (n, why) { score += n; reasons.push("+" + n + " " + why); };
    var regulated = String(l.regulated).toLowerCase() === "true";
    var title = String(l.title || "");
    var signal = String(l.hook || "") + " " + String(l.tags || "");
    if (l.audience === "companies") {
      if (Number(l.employees) >= 50) add(20, "company size 50+");
      if (DECIDER.test(title)) add(20, "decision-maker title");
      if (LEGACY.test(signal)) add(25, "legacy or modernization signal");
      if (daysAgo(l.hook_date) <= 90) add(15, "public trigger in last 90 days");
      if (String(l.funds_evidence || "") !== "") add(10, "evidence of ability to pay");
    } else {
      if (daysAgo(l.funding_date) <= 548) add(30, "funded in last 18 months");
      if (STAGES[String(l.stage || "").toLowerCase()]) add(STAGES[String(l.stage).toLowerCase()], "stage " + l.stage);
      if (DECIDER.test(title)) add(15, "founder or decision-maker title");
      if (/(hiring|first engineer|mvp|launch|building|prototype)/i.test(signal)) add(20, "building signal");
      if (daysAgo(l.hook_date) <= 90) add(10, "public trigger in last 90 days");
    }
    if (String(l.hook_source_url || "").indexOf("http") === 0 && String(l.hook || "").length >= 15) add(10, "specific public hook");
    if (regulated) { score = 0; reasons.push("excluded: regulated domain"); }
    var tier = score >= 60 ? "qualify" : score >= 40 ? "nurture" : "drop";
    return Object.assign({}, l, { score: score, tier: tier, score_reasons: reasons.join("; ") });
  });
})()
